    index += 1;
  }

  return {
    type: 'ol',
    indent: indentInfo.columns,
    contentIndex: index,
  };
}

function findNextNonBlank(lines, start, end) {
  let index = start;
  while (index < end && isBlank(lines[index])) {
    index += 1;
  }
  return index;
}

function startsParagraphInterrupt(line) {
  if (stripBlockquoteMarker(line) !== null) {
    return true;
  }

  if (parseHtmlTagInfo(line)) {
    return true;
  }

  if (parseAtxHeading(line)) {
    return true;
  }

  if (isThematicBreak(line)) {
    return true;
  }

  return false;
}

function startsTailBlock(line) {
  if (isBlank(line)) {
    return true;
  }

  if (detectListMarker(line)) {
    return true;
  }

  if (stripBlockquoteMarker(line) !== null) {
    return true;
  }

  if (parseHtmlTagInfo(line)) {
    return true;
  }

  if (parseAtxHeading(line)) {
    return true;
  }

  if (isThematicBreak(line)) {
    return true;
  }

  return countLeadingColumns(line) >= 4;
}

function unwrapLeadingParagraph(html) {
  if (!html.startsWith('<p>')) {
    return html;
  }

  const closeIndex = html.indexOf('</p>');
  if (closeIndex < 0) {
    return html;
  }

  let remainder = html.slice(closeIndex + 4);
  if (remainder.startsWith('\n')) {
    remainder = remainder.slice(1);
  }

  return html.slice(3, closeIndex) + remainder;
}

function renderLines(lines) {
  const blocks = [];
  let index = 0;

  while (index < lines.length) {
    const line = lines[index];

    if (isBlank(line)) {
      index += 1;
      continue;
    }

    const htmlBlock = parseHtmlBlock(lines, index, lines.length);
    if (htmlBlock) {
      blocks.push(htmlBlock.html);
      index = htmlBlock.nextIndex;
      continue;
    }

    if (index + 1 < lines.length && !isBlank(line)) {
      const setextLevel = getSetextLevel(lines[index + 1]);
      if (setextLevel > 0) {
        blocks.push(`<h${setextLevel}>${renderInline(trimAsciiWhitespace(line))}</h${setextLevel}>`);
        index += 2;
        continue;
      }
    }

    const atxHeading = parseAtxHeading(line);
    if (atxHeading) {
      blocks.push(`<h${atxHeading.level}>${renderInline(trimAsciiWhitespace(atxHeading.text))}</h${atxHeading.level}>`);
      index += 1;
      continue;
    }

    if (isThematicBreak(line)) {
      blocks.push('<hr />');
      index += 1;
      continue;
    }

    const blockquoteLine = stripBlockquoteMarker(line);
    if (blockquoteLine !== null) {
      const quotedLines = [];
      while (index < lines.length) {
        const stripped = stripBlockquoteMarker(lines[index]);
        if (stripped === null) {
          break;
        }
        quotedLines.push(stripped);
        index += 1;
      }

      const innerHtml = renderLines(quotedLines);
      blocks.push(`<blockquote>\n${innerHtml}\n</blockquote>`);
      continue;
    }

    const listMarker = detectListMarker(line);
    if (listMarker) {
      const tagName = listMarker.type === 'ol' ? 'ol' : 'ul';
      const itemIndentLimit = listMarker.indent + 3;
      const items = [];

      while (index < lines.length) {
        if (isBlank(lines[index])) {
          const nextNonBlank = findNextNonBlank(lines, index + 1, lines.length);
          const nextMarker = nextNonBlank < lines.length ? detectListMarker(lines[nextNonBlank]) : null;
          if (nextMarker && nextMarker.type === listMarker.type && nextMarker.indent <= itemIndentLimit) {
            index = nextNonBlank;
            continue;
          }
          break;
        }

        const marker = detectListMarker(lines[index]);
        if (!marker || marker.type !== listMarker.type || marker.indent > itemIndentLimit) {
          break;
        }

        const baseIndent = marker.contentIndex;
        const firstText = lines[index].slice(marker.contentIndex);
        const tailLines = [];
        index += 1;

        while (index < lines.length) {
          const currentLine = lines[index];

          if (isBlank(currentLine)) {
            const nextNonBlank = findNextNonBlank(lines, index + 1, lines.length);
            if (nextNonBlank >= lines.length) {
              index = lines.length;
              break;
            }

            const nextMarker = detectListMarker(lines[nextNonBlank]);
            if (nextMarker && nextMarker.type === listMarker.type && nextMarker.indent <= itemIndentLimit) {
              break;
            }

            const nextIndent = countLeadingColumns(lines[nextNonBlank]);
            if (nextIndent >= baseIndent) {
              tailLines.push('');
              index = nextNonBlank;
              continue;
            }

            break;
          }

          const siblingMarker = detectListMarker(currentLine);
          if (siblingMarker && siblingMarker.type === listMarker.type && siblingMarker.indent <= itemIndentLimit) {
            break;
          }

          const indent = countLeadingColumns(currentLine);
          if (indent >= baseIndent) {
            tailLines.push(stripIndent(currentLine, baseIndent));
            index += 1;
            continue;
          }

          break;
        }

        let itemHtml = '';
        const hasFirstText = !isBlank(firstText);

        if (tailLines.length === 0) {
          itemHtml = hasFirstText ? renderInline(firstText) : '';
        } else {
          let tailNeedsBlocks = false;
          for (let tailIndex = 0; tailIndex < tailLines.length; tailIndex += 1) {
            if (startsTailBlock(tailLines[tailIndex])) {
              tailNeedsBlocks = true;
              break;
            }
          }

          if (!tailNeedsBlocks) {
            const mergedText = hasFirstText ? `${firstText}\n${tailLines.join('\n')}` : tailLines.join('\n');
            itemHtml = renderInline(mergedText);
          } else {
            const tailHtml = renderLines(tailLines);
            if (hasFirstText) {
              itemHtml = renderInline(firstText);
              if (tailHtml) {
                if (tailHtml.startsWith('<ul>') || tailHtml.startsWith('<ol>') || tailHtml.startsWith('<blockquote>') || tailHtml.startsWith('<pre>')) {
                  itemHtml += `${tailHtml}\n`;
                } else {
                  itemHtml += `\n${tailHtml}`;
                }
              }
            } else {
              itemHtml = unwrapLeadingParagraph(tailHtml);
            }
          }
        }

        items.push(`<li>${itemHtml}</li>`);
      }

      blocks.push(`<${tagName}>\n${items.join('\n')}\n</${tagName}>`);
      continue;
    }

    if (countLeadingColumns(line) >= 4) {
      const codeLines = [];
      while (index < lines.length) {
        const currentLine = lines[index];
        if (isBlank(currentLine)) {
          codeLines.push('');
          index += 1;
          continue;
        }

        if (countLeadingColumns(currentLine) < 4) {
          break;
        }

        codeLines.push(stripIndent(currentLine, 4));
        index += 1;
      }

      blocks.push(`<pre><code>${escapeCodeText(codeLines.join('\n'))}\n</code></pre>`);
      continue;
    }

    const paragraphLines = [line];
    index += 1;

    while (index < lines.length && !isBlank(lines[index])) {
      if (startsParagraphInterrupt(lines[index])) {
        break;
      }
      paragraphLines.push(lines[index]);
      index += 1;
    }

    blocks.push(`<p>${renderInline(paragraphLines.join('\n'))}</p>`);
  }

  return blocks.join('\n');
}

export function renderMarkdown(value) {
  const normalized = normalizeNewlines(value);
  const lines = splitLines(normalized);

  let hasContent = false;
  for (let index = 0; index < lines.length; index += 1) {
    if (!isBlank(lines[index])) {
      hasContent = true;
      break;
    }
  }

  if (!hasContent) {
    return '';
  }

  return renderLines(lines);
}

function isSpaceLikeChar(char) {
  return char === ' ' || char === '\t' || char === '\n' || char === '\r' || char === '\f' || char === '\v';
}

export function normalizeNewlines(value) {
  let result = '';

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];

    if (char === '\r') {
      if (index + 1 < value.length && value[index + 1] === '\n') {
        index += 1;
      }
      result += '\n';
      continue;
    }

    result += char;
  }

  return result;
}

export function splitLines(value) {
  const lines = [];
  let start = 0;

  for (let index = 0; index < value.length; index += 1) {
    if (value[index] === '\n') {
      lines.push(value.slice(start, index));
      start = index + 1;
    }
  }

  lines.push(value.slice(start));
  return lines;
}

export function isBlank(value) {
  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }

  return true;
}

export function trimAsciiWhitespace(value) {
  let start = 0;
  let end = value.length;

  while (start < end && isSpaceLikeChar(value[start])) {
    start += 1;
  }

  while (end > start && isSpaceLikeChar(value[end - 1])) {
    end -= 1;
  }

  return value.slice(start, end);
}

export function trimLeadingSpaces(value) {
  let start = 0;

  while (start < value.length && (value[start] === ' ' || value[start] === '\t')) {
    start += 1;
  }

  return value.slice(start);
}

export function countLeadingColumns(value) {
  let columns = 0;

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char === ' ') {
      columns += 1;
      continue;
    }

    if (char === '\t') {
      columns += 4;
      continue;
    }

    break;
  }

  return columns;
}

export function stripIndent(value, width) {
  let columns = 0;
  let index = 0;

  while (index < value.length && columns < width) {
    const char = value[index];

    if (char === ' ') {
      columns += 1;
      index += 1;
      continue;
    }

    if (char === '\t') {
      columns += 4;
      index += 1;
      continue;
    }

    break;
  }

  return value.slice(index);
}

export function getOptionalIndentInfo(value, maxColumns = 3) {
  let columns = 0;
  let index = 0;

  while (index < value.length) {
    const char = value[index];
    if (char !== ' ' && char !== '\t') {
      break;
    }

    columns += char === '\t' ? 4 : 1;
    if (columns > maxColumns) {
      return null;
    }

    index += 1;
  }

  return { columns, index };
}

export function isAsciiDigit(char) {
  return char >= '0' && char <= '9';
}

export function isAsciiLetter(char) {
  return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z');
}

export function isWordLikeChar(char) {
  if (!char) {
    return false;
  }

  if (isAsciiLetter(char) || isAsciiDigit(char)) {
    return true;
  }

  return char.charCodeAt(0) > 127;
}

export function basename(value) {
  if (!value) {
    return '';
  }

  let start = 0;

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char === '/' || char === '\\') {
      start = index + 1;
    }
  }

  return value.slice(start);
}
